    39	/**
    40	 * Calculates the amount per user given a list of participants
    41	 *
    42	 * @param numberOfParticipants - Number of participants in the chat. It should not include the current user.
    43	 * @param total - IOU total amount in backend format (cents, no matter the currency)
    44	 * @param currency - This is used to know how many decimal places are valid to use when splitting the total
    45	 * @param isDefaultUser - Whether we are calculating the amount for the current user
    46	 */
    47	function calculateAmount(numberOfParticipants: number, total: number, currency: string, isDefaultUser = false): number {
    48	    // Since the backend can maximum store 2 decimal places, any currency with more than 2 decimals
    49	    // has to be capped to 2 decimal places
    50	    const currencyUnit = Math.min(100, CurrencyUtils.getCurrencyUnit(currency));
    51	    const totalInCurrencySubunit = Math.round((total / 100) * currencyUnit);
    52	    const totalParticipants = numberOfParticipants + 1;
    53	    const amountPerPerson = Math.round(totalInCurrencySubunit / totalParticipants);
    54	    let finalAmount = amountPerPerson;
    55	    if (isDefaultUser) {
    56	        const sumAmount = amountPerPerson * totalParticipants;
    57	        const difference = totalInCurrencySubunit - sumAmount;
    58	        finalAmount = totalInCurrencySubunit !== sumAmount ? amountPerPerson + difference : amountPerPerson;
    59	    }
    60	    return Math.round((finalAmount * 100) / currencyUnit);
    61	}
